INSERT INTO questionnaires (language, questionnaire) VALUES ('SR', '{"info":[{"QuestionType":"intro","settings":{"RichText":"<h1>Dobrodošli</h1><p>Menopauza nije kraj jedne faze, već prirodni deo vašeg života u kojem su vam potrebne jasne informacije i odgovarajuća podrška.</p><p>Naš upitnik vam pomaže da prepoznate u kojoj ste fazi menopauze i pruža vam naučno zasnovane informacije za podršku vašem zdravlju.<br><br>Niste same na ovom putu.<br>Tu smo da vam pružimo jasnoću i stvarnu podršku.</p><p>Hajde da počnemo.</p>"},"DataPointName":"WelcomeMessage","position":1},{"QuestionType":"media","settings":{"RichText":"<h1>Preko 1000 žena<br>je izabralo Primea</h1>","MediaUrl":"https://cdn.shopify.com/s/files/1/0799/1132/1784/files/community.png"},"DataPointName":"Media","position":2},{"QuestionType":"first_name","settings":{"QuestionHelper":"Molimo vas unesite vaše ime.","QuestionText":"Kako se zovete?"},"DataPointName":"FirstName","position":3},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"Ovo polje je obavezno.","label":"Godina rođenja","type":"numeric","mandatory":true,"measurement":"Godina"}],"QuestionHelper":"Molimo vas unesite godinu u kojoj ste rođeni.","QuestionText":"Koja je vaša godina rođenja?"},"DataPointName":"BirthYear","position":4},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"Ovo polje je obavezno.","label":"Visina","type":"numeric","mandatory":true,"measurement":"cm"}],"QuestionHelper":"Molimo vas unesite vašu visinu u centimetrima.","QuestionText":"Kolika je vaša visina?"},"DataPointName":"Height","position":5},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"Ovo polje je obavezno.","label":"Težina","type":"numeric","mandatory":true,"measurement":"kg"}],"QuestionHelper":"Molimo vas unesite vašu težinu u kilogramima.","QuestionText":"Kolika je vaša trenutna težina?"},"DataPointName":"Weight","position":6},{"QuestionType":"single_option","settings":{"options":[{"OptionText":"Imam redov